BEGIN;

-- FPR initial PostgreSQL schema.
--
-- Principles:
-- - single-fund application: no funds table and no fund_id columns;
-- - PostgreSQL stores structure and durable state;
-- - business validation lives in Go, so domain CHECK/regex constraints are intentionally absent;
-- - initial data consists of historical disclosures and price references;
-- - normal public runtime reads are served from RAM state built from this durable data.

CREATE TABLE instruments (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    asset_type TEXT NOT NULL,
    isin TEXT NOT NULL UNIQUE,

    name TEXT NOT NULL,
    issuer TEXT,
    ticker TEXT,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


CREATE TABLE bond_details (
    instrument_id BIGINT PRIMARY KEY
        REFERENCES instruments (id)
        ON DELETE CASCADE,

    nominal_value NUMERIC,
    nominal_currency TEXT,

    maturity_date DATE,
    coupon_rate_percent NUMERIC,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Canonical official daily history from the management company page.
-- Initial backfill may insert missing dates of any age.
-- For already stored dates the application may update values only inside the
-- fresh seven-calendar-day correction window relative to the latest source date.
-- Older source mismatches are diagnostics and do not overwrite stored history.
CREATE TABLE fund_daily_values (
    as_of_date DATE PRIMARY KEY,

    calculated_unit_value_usd NUMERIC NOT NULL,
    nav_usd NUMERIC NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Immutable/versioned snapshots of the current management company page.
-- The same as_of_date may have multiple versions when the management company changes current data.
CREATE TABLE fund_snapshots (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    as_of_date DATE NOT NULL,
    observed_at TIMESTAMPTZ NOT NULL,

    source_hash TEXT NOT NULL,

    calculated_unit_value_usd NUMERIC NOT NULL,
    nav_usd NUMERIC NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (as_of_date, source_hash)
);

CREATE INDEX fund_snapshots_latest_idx
    ON fund_snapshots (
        as_of_date DESC,
        observed_at DESC,
        id DESC
    );


-- Exact rows from the management company "Структура активов" table.
-- For current securities instrument_id and quantity are required by Go validation.
-- For cash/claims/etc. they are intentionally NULL.
CREATE TABLE fund_snapshot_assets (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    snapshot_id BIGINT NOT NULL
        REFERENCES fund_snapshots (id)
        ON DELETE CASCADE,

    row_no SMALLINT NOT NULL,

    source_name TEXT NOT NULL,
    source_type TEXT NOT NULL,

    instrument_id BIGINT
        REFERENCES instruments (id),

    currency TEXT,
    quantity NUMERIC,

    asset_share_percent NUMERIC NOT NULL,
    asset_share_upper_bound BOOLEAN NOT NULL DEFAULT false,

    UNIQUE (snapshot_id, row_no)
);

CREATE INDEX fund_snapshot_assets_instrument_idx
    ON fund_snapshot_assets (instrument_id)
    WHERE instrument_id IS NOT NULL;


-- More precise category shares published by the management company separately from rounded detail rows.
CREATE TABLE fund_snapshot_categories (
    snapshot_id BIGINT NOT NULL
        REFERENCES fund_snapshots (id)
        ON DELETE CASCADE,

    row_no SMALLINT NOT NULL,

    source_name TEXT NOT NULL,
    asset_share_percent NUMERIC NOT NULL,

    PRIMARY KEY (snapshot_id, row_no)
);


-- Confirmed number of fund units from periodic official PDF reports.
CREATE TABLE fund_unit_counts (
    as_of_date DATE PRIMARY KEY,

    units_outstanding NUMERIC NOT NULL,

    source_url TEXT NOT NULL,
    observed_at TIMESTAMPTZ NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Provider-specific market-price mapping.
CREATE TABLE instrument_price_sources (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    instrument_id BIGINT NOT NULL
        REFERENCES instruments (id)
        ON DELETE CASCADE,

    provider TEXT NOT NULL,
    provider_symbol TEXT NOT NULL,

    enabled BOOLEAN NOT NULL DEFAULT true,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    UNIQUE (instrument_id, provider)
);


-- Last durable normalized valuation price for a price source.
-- unit_value is normalized so it can be multiplied by the position quantity.
CREATE TABLE instrument_prices (
    price_source_id BIGINT PRIMARY KEY
        REFERENCES instrument_price_sources (id)
        ON DELETE CASCADE,

    unit_value NUMERIC NOT NULL,
    currency TEXT NOT NULL,

    priced_at TIMESTAMPTZ NOT NULL,
    fetched_at TIMESTAMPTZ NOT NULL,
    previous_close NUMERIC CHECK (previous_close > 0),
    imported_provider TEXT
);


-- Short intraday history for UI mini-charts.
-- Retention is controlled by Go/scheduler; initial target is about 48 hours.
CREATE TABLE instrument_price_points (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    price_source_id BIGINT NOT NULL
        REFERENCES instrument_price_sources (id)
        ON DELETE CASCADE,

    unit_value NUMERIC NOT NULL,
    currency TEXT NOT NULL,

    priced_at TIMESTAMPTZ NOT NULL,
    observed_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX instrument_price_points_history_idx
    ON instrument_price_points (
        price_source_id,
        observed_at DESC
    );


-- Permanent daily market-price series when useful.
-- Initially this is primarily the MOEX history of the fund unit (БСИП).
CREATE TABLE instrument_daily_prices (
    price_source_id BIGINT NOT NULL
        REFERENCES instrument_price_sources (id)
        ON DELETE CASCADE,

    price_date DATE NOT NULL,

    unit_value NUMERIC NOT NULL,
    currency TEXT NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (price_source_id, price_date)
);


-- Current FX rates needed by live valuation.
-- Historical FX is not part of the initial schema; each baseline persists the
-- exact FX rate used by that baseline calculation.
CREATE TABLE fx_rates (
    base_currency TEXT NOT NULL,
    quote_currency TEXT NOT NULL,

    provider TEXT NOT NULL,
    rate NUMERIC NOT NULL,

    priced_at TIMESTAMPTZ NOT NULL,
    fetched_at TIMESTAMPTZ NOT NULL,

    PRIMARY KEY (base_currency, quote_currency)
);


-- Market baseline for an official snapshot asset.
-- This is derived FPR data, not a fact published by the management company.
-- It lets live valuation survive restart without reconstructing old quotes.
CREATE TABLE fund_snapshot_price_baselines (
    asset_id BIGINT PRIMARY KEY
        REFERENCES fund_snapshot_assets (id)
        ON DELETE CASCADE,

    price_source_id BIGINT NOT NULL
        REFERENCES instrument_price_sources (id),

    unit_value NUMERIC NOT NULL,
    currency TEXT NOT NULL,
    priced_at TIMESTAMPTZ NOT NULL,

    fx_rate_to_usd NUMERIC NOT NULL,
    fx_provider TEXT NOT NULL,
    fx_priced_at TIMESTAMPTZ NOT NULL,

    market_value_usd NUMERIC NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Short history of calculated live fund value for UI mini-charts.
CREATE TABLE fund_value_points (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    snapshot_id BIGINT NOT NULL
        REFERENCES fund_snapshots (id)
        ON DELETE CASCADE,

    observed_at TIMESTAMPTZ NOT NULL,

    estimated_nav_usd NUMERIC NOT NULL,
    estimated_calculated_unit_value_usd NUMERIC NOT NULL,

    live_delta_usd NUMERIC NOT NULL,
    live_coverage_percent NUMERIC NOT NULL
);

CREATE INDEX fund_value_points_history_idx
    ON fund_value_points (observed_at DESC);


-- Bond-specific current market metrics for UI and valuation diagnostics.
-- instrument_prices.unit_value remains the normalized common valuation value;
-- clean/accrued/YTM stay bond-specific here.
CREATE TABLE bond_market_data (
    instrument_id BIGINT PRIMARY KEY
        REFERENCES instruments (id)
        ON DELETE CASCADE,

    price_source_id BIGINT NOT NULL
        REFERENCES instrument_price_sources (id)
        ON DELETE CASCADE,

    currency TEXT NOT NULL,

    clean_unit_value NUMERIC,
    accrued_coupon_unit_value NUMERIC,
    yield_to_maturity_percent NUMERIC,

    priced_at TIMESTAMPTZ NOT NULL,
    fetched_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE scheduler_job_runs
(
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    job_key     TEXT        NOT NULL,
    run_source  TEXT        NOT NULL,

    status      TEXT        NOT NULL,

    summary     JSONB       NOT NULL DEFAULT '{}'::jsonb,
    message     JSONB       NOT NULL DEFAULT '[]'::jsonb,
    error       TEXT        NOT NULL DEFAULT '',

    started_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ
);

CREATE INDEX scheduler_job_runs_job_key_started_idx
    ON scheduler_job_runs (job_key, started_at DESC);

CREATE INDEX scheduler_job_runs_status_started_idx
    ON scheduler_job_runs (status, started_at DESC);

-- A report is imported atomically as one document. Its original source and
-- digest stay available even when the management company issues a correction.
CREATE TABLE fund_portfolio_reports (
    as_of_date DATE NOT NULL,
    source_sha256 TEXT NOT NULL,
    report JSONB NOT NULL,
    seeded BOOLEAN NOT NULL DEFAULT false,
    imported_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (as_of_date, source_sha256)
);

CREATE TABLE fund_portfolio_references (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    reference JSONB NOT NULL,
    seeded BOOLEAN NOT NULL DEFAULT false
);

-- Security weights from the August checkpoints saved by the website collector in Архив.zip.
-- Live checkpoints take precedence when the same date exists in fund_snapshots.
CREATE TABLE fund_archived_composition (
    as_of_date DATE NOT NULL,
    isin TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL,
    quantity NUMERIC NOT NULL,
    asset_share_percent NUMERIC NOT NULL,
    asset_share_upper_bound BOOLEAN NOT NULL,
    row_count INTEGER NOT NULL,
    PRIMARY KEY (as_of_date, isin)
);

-- Confirmed reports from the management company, with source and PDF digest.
ON CONFLICT (as_of_date, source_sha256) DO NOTHING;

-- Public source rows from the user-maintained sheet and selected stocks from the older FPR.


-- Market-price mappings and last quotes recovered from the previous backend backup.
-- imported_provider records where the saved quote came from until the configured source returns a quote.
WITH seed (isin, asset_type, name, symbol, provider, imported_provider, unit_value, currency, priced_at, fetched_at) AS (
    VALUES
        ('IL0011786493', 'equity', 'Riskified ltd', 'RSKD', 'nasdaq', 'yahoo', 6.19, 'USD', TIMESTAMPTZ '2026-09-01 20:00:02.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('KZ1C00001122', 'equity', 'АО "Национальная компания "КазМунайГаз"', 'KMGZ', 'kase', NULL, NULL, NULL, NULL, NULL),
        ('RU000A0JQ9P9', 'equity', 'ПУБЛИЧНОЕ АКЦИОНЕРНОЕ ОБЩЕСТВО "СПБ БИРЖА"', 'SPBE', 'moex', 'moex', 129.3, 'RUB', TIMESTAMPTZ '2026-09-01 20:49:53.000000 +00:00', TIMESTAMPTZ '2026-09-01 21:48:00.318067 +00:00'),
        ('US1263271058', 'equity', 'CS Disco Inc', 'LAW', 'nasdaq', 'yahoo', 4.23, 'USD', TIMESTAMPTZ '2026-09-01 20:00:02.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US23285D1090', 'equity', 'Cytek Biosciences Inc', 'CTKB', 'nasdaq', 'yahoo', 4.62, 'USD', TIMESTAMPTZ '2026-09-01 20:00:01.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US3563901046', 'equity', 'Freedom Holding Corporation', 'FRHC', 'nasdaq', 'yahoo', 171.87, 'USD', TIMESTAMPTZ '2026-09-01 20:00:01.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US52635N1037', 'equity', 'LENZ Therapeutics, Inc', 'LENZ', 'nasdaq', 'yahoo', 5.23, 'USD', TIMESTAMPTZ '2026-09-01 20:00:01.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US64082B1026', 'equity', 'NerdWallet Inc.', 'NRDS', 'nasdaq', 'yahoo', 9.78, 'USD', TIMESTAMPTZ '2026-09-01 20:00:00.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US75340L1044', 'equity', 'Rapid Micro Biosystems Inc', 'RPID', 'nasdaq', 'yahoo', 1.5, 'USD', TIMESTAMPTZ '2026-09-01 20:00:01.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US75960P1049', 'equity', 'Remitly Global Inc', 'RELY', 'nasdaq', 'yahoo', 25.71, 'USD', TIMESTAMPTZ '2026-09-01 20:00:00.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US78349D1072', 'equity', 'RxSight Inc', 'RXST', 'nasdaq', 'yahoo', 6.99, 'USD', TIMESTAMPTZ '2026-09-01 20:00:00.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US81730H1095', 'equity', 'SentinelOne Inc', 'S', 'nasdaq', 'yahoo', 20.63, 'USD', TIMESTAMPTZ '2026-09-01 20:00:02.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US82489W1071', 'equity', 'Shoals Technologies Group Inc', 'SHLS', 'nasdaq', 'yahoo', 6.7, 'USD', TIMESTAMPTZ '2026-09-01 20:00:00.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US82657M1053', 'equity', 'Sight Sciences Inc', 'SGHT', 'nasdaq', 'yahoo', 8.19, 'USD', TIMESTAMPTZ '2026-09-01 20:00:01.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00'),
        ('US85208T1079', 'equity', 'Sprinklr Inc', 'CXM', 'nasdaq', 'yahoo', 7.6, 'USD', TIMESTAMPTZ '2026-09-01 20:00:03.000000 +00:00', TIMESTAMPTZ '2026-09-01 20:22:00.492296 +00:00')
), inserted_instruments AS (
    SELECT isin, asset_type, name FROM seed
    RETURNING id, isin
), inserted_sources AS (
    SELECT instrument.id, seed.provider, seed.symbol
    FROM seed
    JOIN inserted_instruments AS instrument USING (isin)
    RETURNING id, instrument_id
)
SELECT source.id, seed.unit_value, seed.currency, seed.priced_at, seed.fetched_at, seed.imported_provider
FROM seed
JOIN inserted_instruments AS instrument USING (isin)
JOIN inserted_sources AS source ON source.instrument_id = instrument.id
WHERE seed.unit_value IS NOT NULL;

COMMIT;
